contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        uint balanceBefore = c.tokenBalance(address(this));

        require(balanceBefore == 0, "precondition: caller must have no token balance");

        bool reverted;
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balanceAfter = c.tokenBalance(address(this));

        assert(!reverted && balanceAfter == balanceBefore + 20);
    }

    receive() external payable {}
}

