contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public payable {
        require(caller != address(0));
        require(caller != address(c));

        bytes32 expected = keccak256(abi.encodePacked("Nu Token"));
        (bool ok, bytes memory data) = caller.staticcall(abi.encodeWithSignature("supportsToken()"));
        require(ok && data.length == 32);
        bytes32 supported = abi.decode(data, (bytes32));
        require(supported == expected);

        uint before = c.tokenBalance(caller);
        require(before == 0);

        c.airDrop();

        assert(c.tokenBalance(caller) == 20);
    }

    receive() external payable {}
}

contract InvMutTest {
