contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address bank) public {
        require(bank != address(0));

        uint beforeBank = c.tokenBalance(bank);
        uint beforeThis = c.tokenBalance(address(this));
        uint beforeBal = address(c).balance;

        bool reverted;
        try c.airDrop() { reverted = false; } catch { reverted = true; }

        if (reverted) {
            // If the call reverted, no tokens may have moved and the lock must be released.
            assert(c.tokenBalance(bank) == beforeBank && c.tokenBalance(address(this)) == beforeThis && !c._locked());
        } else {
            // If the call succeeded, exactly +20 tokens went to the tester and the lock is released.
            assert(
                c.tokenBalance(address(this)) == beforeThis + 20 &&
                c.tokenBalance(bank) == beforeBank &&
                address(c).balance == beforeBal &&
                !c._locked() &&
                Bank(bank).supportsToken() == keccak256(abi.encodePacked("Nu Token"))
            );
        }
    }
}

